/// Registers plugins into the shared tool catalog so any app/agent can consume
/// their tools as first-class `<pluginId>.<tool>` entries.
///
/// This is pure composition of kernel primitives — no new kernel concept:
/// - **server / hub**: `KernelClientHost.connect` → `listTools` → mirror each
///   tool with `HostToolRegistry.registerExposed` (handler routes to the
///   connection's `callTool`). Turns "the app drives `mcp.*` by hand" into
///   "register once, the tools are in the catalog".
/// - **bundle**: the host activates the bundle in plugin mode (kernel
///   `BundleActivation`, no UI mount) — activation already registers its tools
///   under the plugin id. [registerBundle] just records it for lifecycle.
///
/// Which agent sees which tool stays per-agent scoping; being in the catalog
/// does not make a tool visible to every agent.
library;

import 'dart:async';
import 'dart:convert';

import 'package:brain_kernel/brain_kernel.dart';
import 'package:brain_kernel/mcp_host.dart' show ToolListChangeSource;

import 'plugin_access.dart';
import 'plugin_source.dart';

/// A registered plugin and the catalog entries it owns.
class RegisteredPlugin {
  RegisteredPlugin({
    required this.source,
    required this.rawNames,
    required this.exposedNames,
    this.connection,
    this.unavailable,
    this.detail = '',
  });

  final PluginSource source;

  /// Unprefixed tool names (used to unregister).
  List<String> rawNames;

  /// Catalog names (`<pluginId>.<tool>`) other apps/agents call.
  List<String> exposedNames;

  /// The live connection for `server`/`hub` kinds (null for `bundle`).
  KernelClientConnection? connection;

  /// Watches the server's tool list while connected (see [PluginHost.refresh]).
  StreamSubscription<void>? watch;

  /// Null while serving; otherwise why the plugin is not.
  PluginUnavailable? unavailable;

  /// Free-text detail of [unavailable] for the person.
  String detail;

  bool get isConnected => unavailable == null;
}

class PluginHost {
  PluginHost(
    this._registry, {
    KernelClientHost? clientHost,
    PluginAccessProvider? accessProvider,
    bool Function(String namespace)? isNamespaceTaken,
    void Function(String note)? onNote,
  })  : _clientHost = clientHost,
        _accessProvider = accessProvider,
        _isNamespaceTaken = isNamespaceTaken,
        _onNote = onNote;

  final HostToolRegistry _registry;
  final KernelClientHost? _clientHost;
  final PluginAccessProvider? _accessProvider;
  final bool Function(String namespace)? _isNamespaceTaken;
  final void Function(String note)? _onNote;
  final Map<String, RegisteredPlugin> _plugins = <String, RegisteredPlugin>{};

  /// Every registered plugin, serving or not.
  Iterable<RegisteredPlugin> get plugins => _plugins.values;
  RegisteredPlugin? plugin(String id) => _plugins[id];

  /// Connect a `server`/`hub` plugin and mirror its `tools/list` into the
  /// catalog under `<source.id>.<tool>`. Each handler routes to the
  /// connection so a call reaches the real server.
  ///
  /// Registering an id that is already a plugin replaces it: the old entries
  /// come down completely before the new ones go up.
  /// [toolRawNames] (optional, else `source.tools`) restricts the mirror to
  /// those tool names — a whitelist for large servers. Null mirrors every
  /// tool the server lists.
  Future<RegisteredPlugin> registerServer(
    PluginSource source, {
    Iterable<String>? toolRawNames,
  }) async {
    final host = _clientHost;
    if (host == null) {
      throw StateError(
        'registerServer requires a KernelClientHost — the host must boot with '
        'one (clientHost). bundle plugins do not need it.',
      );
    }
    _checkId(source.id);
    final access = await _access(source);
    await _drop(source.id);
    final conn = access.connection ??
        await host.connect(
          id: source.id,
          transport: access.transport,
          endpoint: access.endpoint,
          options: access.options,
        );
    final tools = await conn.listTools();
    final wanted = (toolRawNames ?? source.tools)?.toSet();
    final reg = RegisteredPlugin(
      source: source,
      rawNames: <String>[],
      exposedNames: <String>[],
      connection: conn,
    );
    _plugins[source.id] = reg;
    _mirror(reg, tools, wanted);
    _watch(reg);
    return reg;
  }

  /// Record a `bundle` plugin whose tools the host already wired via the
  /// kernel `BundleActivation` (plugin mode = activate without mounting UI).
  /// [toolRawNames] are the activated bundle's tool names (without the id
  /// prefix) so [unregister] can tear them down symmetrically.
  RegisteredPlugin registerBundle(
    PluginSource source, {
    required List<String> toolRawNames,
  }) {
    _checkId(source.id);
    final old = _plugins.remove(source.id);
    if (old != null) _unmirror(old);
    final reg = RegisteredPlugin(
      source: source,
      rawNames: toolRawNames,
      exposedNames: [for (final n in toolRawNames) '${source.id}.$n'],
    );
    _plugins[source.id] = reg;
    return reg;
  }

  /// Keep a stored plugin that cannot serve right now visible with its reason
  /// (a failed boot restore, a missing bundle, a gated source, no consent).
  /// It owns no catalog entries until it connects.
  RegisteredPlugin markUnavailable(
    PluginSource source,
    PluginUnavailable reason, {
    String detail = '',
  }) {
    final old = _plugins[source.id];
    if (old != null) {
      old.unavailable = reason;
      old.detail = detail;
      return old;
    }
    final reg = RegisteredPlugin(
      source: source,
      rawNames: <String>[],
      exposedNames: <String>[],
      unavailable: reason,
      detail: detail,
    );
    _plugins[source.id] = reg;
    return reg;
  }

  /// Connect again and bring the mirror back in line with the server's tool
  /// list: new tools appear, vanished ones leave. For a door-issued source the
  /// access is requested again. A source that cannot connect stays registered
  /// as unavailable with the reason.
  Future<RegisteredPlugin> reconnect(String id) async {
    final reg = _plugins[id];
    if (reg == null) {
      throw PluginError('plugin.bad_input', 'no plugin "$id"');
    }
    final host = _clientHost;
    if (host == null || reg.source.kind == PluginKind.bundle) return reg;
    try {
      final access = await _access(reg.source);
      await reg.connection?.close();
      final conn = access.connection ??
          await host.connect(
            id: id,
            transport: access.transport,
            endpoint: access.endpoint,
            options: access.options,
          );
      final tools = await conn.listTools();
      reg.connection = conn;
      reg.unavailable = null;
      reg.detail = '';
      _mirror(reg, tools, reg.source.tools?.toSet());
      _watch(reg);
    } on PluginAccessException catch (e) {
      reg.unavailable = e.reason;
      reg.detail = e.message;
    } catch (e) {
      // The raw failure is for the log; what a person reads is the reason.
      _onNote?.call('plugin.reconnect.failed $id: $e');
      reg.unavailable = PluginUnavailable.unreachable;
      reg.detail = '';
    }
    return reg;
  }

  /// Read the server's tool list again and bring the catalog in line with it,
  /// without reconnecting. Runs by itself when the connection reports a change
  /// (it implements `ToolListChangeSource`); a host may also call it.
  Future<void> refresh(String id) async {
    final reg = _plugins[id];
    final conn = reg?.connection;
    if (reg == null || conn == null || !conn.isConnected) return;
    try {
      final tools = await conn.listTools();
      _mirror(reg, tools, reg.source.tools?.toSet());
    } catch (e) {
      _onNote?.call('plugin.refresh.failed $id: $e');
    }
  }

  void _watch(RegisteredPlugin reg) {
    unawaited(reg.watch?.cancel());
    reg.watch = null;
    final conn = reg.connection;
    if (conn is! ToolListChangeSource) return;
    reg.watch = (conn as ToolListChangeSource).toolsChanged.listen(
          (_) => unawaited(refresh(reg.source.id)),
        );
  }

  /// Remove a plugin's catalog entries and close any connection.
  Future<void> unregister(String id) => _drop(id);

  Future<void> _drop(String id) async {
    final reg = _plugins.remove(id);
    if (reg == null) return;
    _unmirror(reg);
    await reg.connection?.close();
  }

  void _unmirror(RegisteredPlugin reg) {
    unawaited(reg.watch?.cancel());
    reg.watch = null;
    for (final raw in reg.rawNames) {
      _registry.unregisterExposed(bundleId: reg.source.id, rawName: raw);
    }
    reg.rawNames = <String>[];
    reg.exposedNames = <String>[];
  }

  /// Bring the catalog entries of [reg] in line with [tools].
  void _mirror(
    RegisteredPlugin reg,
    List<KernelToolDescriptor> tools,
    Set<String>? wanted,
  ) {
    final id = reg.source.id;
    final destructive = (reg.source.destructiveTools ?? const <String>[]).toSet();
    final next = <String>[];
    final exposed = <String>[];
    for (final t in tools) {
      if (wanted != null && !wanted.contains(t.name)) continue;
      // A name that is already in the catalog is replaced, not added twice: a
      // real MCP server refuses a second tool of the same name, so a changed
      // list (or a reconnect) would otherwise leave the old entry as it was.
      if (reg.rawNames.contains(t.name)) {
        _registry.unregisterExposed(bundleId: id, rawName: t.name);
      }
      exposed.add(_registry.registerExposed(
        bundleId: id,
        rawName: t.name,
        description: t.description,
        inputSchema: t.inputSchema,
        // The person's own list, or the server's explicit claim. A tool the
        // server did not mark is not assumed safe: the registration approval
        // is what stands behind it.
        destructive: destructive.contains(t.name) || t.destructiveHint == true,
        handler: (args) => _call(id, t.name, args),
      ));
      next.add(t.name);
    }
    for (final gone in reg.rawNames.where((n) => !next.contains(n))) {
      _registry.unregisterExposed(bundleId: id, rawName: gone);
    }
    reg.rawNames = next;
    reg.exposedNames = exposed;
  }

  /// Route a catalog call to the plugin's connection. A door-issued source
  /// asks for fresh access once when the call finds the connection gone; any
  /// plugin that cannot serve answers with its reason, never silence.
  Future<KernelToolResult> _call(
    String id,
    String tool,
    Map<String, dynamic> args,
  ) async {
    final reg = _plugins[id];
    if (reg == null) return _unavailable(id, PluginUnavailable.unreachable, 'unregistered');
    if (reg.unavailable != null && !reg.source.isDoorIssued) {
      return _unavailable(id, reg.unavailable!, reg.detail);
    }
    if (reg.unavailable != null || !(reg.connection?.isConnected ?? false)) {
      if (!reg.source.isDoorIssued) {
        return _unavailable(id, PluginUnavailable.unreachable, 'connection closed');
      }
      await reconnect(id);
      if (reg.unavailable != null) {
        return _unavailable(id, reg.unavailable!, reg.detail);
      }
    }
    try {
      return await reg.connection!.callTool(tool, args);
    } catch (e) {
      if (!reg.source.isDoorIssued) rethrow;
      await reconnect(id);
      if (reg.unavailable != null) {
        return _unavailable(id, reg.unavailable!, reg.detail);
      }
      return reg.connection!.callTool(tool, args);
    }
  }

  KernelToolResult _unavailable(
    String id,
    PluginUnavailable reason,
    String detail,
  ) {
    return KernelToolResult(
      content: [
        KernelTextContent(
          text: jsonEncode(<String, dynamic>{
            'ok': false,
            'error': 'plugin.unavailable',
            'plugin': id,
            'reason': reason.wire,
            if (detail.isNotEmpty) 'detail': detail,
          }),
        ),
      ],
      isError: true,
    );
  }

  Future<PluginAccess> _access(PluginSource source) async {
    if (!source.isDoorIssued) {
      return PluginAccess(
        transport: source.transport ?? KernelTransportKind.streamableHttp,
        endpoint: source.endpoint,
        options: source.options,
      );
    }
    final provider = _accessProvider;
    if (provider == null) {
      throw const PluginError(
        'plugin.market_unavailable',
        'this host has no connection door for door-issued plugins',
      );
    }
    return provider(source);
  }

  void _checkId(String id) {
    if (id.isEmpty || id.contains('.') || id.trim() != id) {
      throw PluginError(
        'plugin.bad_input',
        'id must be a non-empty name without dots or surrounding spaces',
      );
    }
    if (_plugins.containsKey(id)) return; // re-registering replaces
    final prefix = '$id.';
    final taken = (_isNamespaceTaken?.call(id) ?? false) ||
        _registry.endpoint.toolDefinitions.any((d) => d.name.startsWith(prefix));
    if (taken) {
      throw PluginError('plugin.id_taken', 'tools named "$id.*" already exist');
    }
  }
}
